                                   int from, int to, int[] temp)
{
  if (from < to)
  {
    int middle = (from + to) / 2;
    mergeSortHelper(arr, from, middle, temp);
    mergeSortHelper(arr, middle + 1, to, temp);
    merge(arr, from, middle, to, temp);
